import pandas as pd
import numpy as np
import re

def clean_value(val):
    if pd.isna(val) or val == '':
        return np.nan
    if isinstance(val, str):
        val = val.replace(',', '.')
        try:
            return float(val)
        except ValueError:
            return np.nan
    return float(val)

# Define harmonization rules
# key: (min_us, max_us, si_to_us_factor)
rules = {
    'Serum_Creatinine': (0.4, 30.0, 1/88.4),
    'BUN': (2.0, 250.0, 2.8),
    'Magnesium': (0.5, 10.0, 2.43),
    'Serum_Calcium': (4.0, 18.0, 4.0),
    'Ionized_Calcium': (2.0, 8.0, 4.0), # common to have mmol/L (1.1-1.4) -> mg/dL (4.4-5.6)
    'Phosphorus': (0.5, 25.0, 3.1),
    'Vitamin_D_25OH': (2.0, 200.0, 0.4),
    'Hemoglobin': (3.0, 25.0, 0.1),
    'Hematocrit': (10.0, 75.0, 1.0), # sometimes fraction? if < 1.0 maybe * 100
    'Serum_Iron': (10.0, 600.0, 5.59),
    'Total_Bilirubin': (0.05, 50.0, 1/17.1),
    'Direct_Bilirubin': (0.01, 30.0, 1/17.1),
    'Albumin_Serum': (1.0, 8.0, 0.1),
    'Total_Protein': (2.0, 15.0, 0.1),
    'Total_Cholesterol': (40.0, 800.0, 38.67),
    'LDL_Cholesterol': (10.0, 600.0, 38.67),
    'HDL_Cholesterol': (5.0, 200.0, 38.67),
    'Triglycerides': (10.0, 3000.0, 88.5),
    'Glucose': (20.0, 1500.0, 18.0),
    'Uric_Acid': (1.0, 30.0, 1/59.48),
    'Free_T4': (0.1, 15.0, 1/12.87),
    'Free_T3': (0.5, 25.0, 1/1.54),
    'Lactate': (0.1, 200.0, 9.01), # mmol/L to mg/dL
}

def harmonize(col_name, val):
    if pd.isna(val):
        return val

    if col_name in rules:
        min_v, max_v, factor = rules[col_name]
        # If value is way too high, try applying factor (if factor < 1)
        if val > max_v and factor < 1:
            if min_v <= val * factor <= max_v:
                val = val * factor
        # If value is way too low, try applying factor (if factor > 1)
        elif val < min_v and factor > 1:
            if min_v <= val * factor <= max_v:
                val = val * factor
        # Special case for Hemoglobin/Albumin/Protein which are often in g/L (factor 0.1)
        elif val > max_v and factor == 0.1:
             if min_v <= val * 0.1 <= max_v:
                val = val * 0.1
        # Special case for Hematocrit if in fraction
        elif col_name == 'Hematocrit' and val < 1.0:
            if 10.0 <= val * 100 <= 75.0:
                val = val * 100

    return val

def process():
    df = pd.read_csv('/root/environment/data/ckd_lab_data.csv', dtype=str)

    # 1. Drop rows with missing values
    df = df.replace('', np.nan)
    df = df.dropna()

    # 2. Clean values (scientific notation and commas)
    for col in df.columns:
        if col == 'patient_id':
            continue
        df[col] = df[col].apply(clean_value)

    # Drop rows again if cleaning produced NaNs
    df = df.dropna()

    # 3. Harmonize
    for col in df.columns:
        if col == 'patient_id':
            continue
        df[col] = df[col].apply(lambda x: harmonize(col, x))

    # 4. Round to 2 decimal places and format as X.XX
    for col in df.columns:
        if col == 'patient_id':
            # Ensure patient_id is integer if it was string
            df[col] = df[col].astype(float).astype(int)
            continue
        df[col] = df[col].apply(lambda x: f"{x:.2f}")

    df.to_csv('/root/ckd_lab_data_harmonized.csv', index=False)

